foreach($patterns as $search => $replace) {
    if (strpos($content, $search) !== false) {
        $content = str_replace($search, $replace, $content);
    } else {
        // Fallback for linebreaks using regex
        $searchP = preg_quote($search, '/');
        $searchP = preg_replace('/\s+/', '\s+', $searchP);
        $content = preg_replace('/' . $searchP . '/', $replace, $content);
    }
}
