// Apply translations
function appendArrayToFile2($path, $extraData) {
    $existing = require $path;
    $merged = array_merge($existing, $extraData);
    $content = "<?php\n\nreturn " . var_export($merged, true) . ";\n";
    file_put_contents($path, $content);
}

